insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('documents','documents',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict (id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types; do $$ begin if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='document_storage_owner_insert') then create policy document_storage_owner_insert on storage.objects for insert to authenticated with check (bucket_id='documents' and (storage.foldername(name))[1]='households' and (storage.foldername(name))[2]=(select auth.uid()::text)); end if; if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='document_storage_owner_select') then create policy document_storage_owner_select on storage.objects for select to authenticated using (bucket_id='documents' and (storage.foldername(name))[1]='households' and (storage.foldername(name))[2]=(select auth.uid()::text)); end if; if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='document_storage_owner_delete') then create policy document_storage_owner_delete on storage.objects for delete to authenticated using (bucket_id='documents' and (storage.foldername(name))[1]='households' and (storage.foldername(name))[2]=(select auth.uid()::text)); end if; end $$
